{"sql": "-- Create lego_colors table
CREATE TABLE IF NOT EXISTS lego_colors (
    id INTEGER PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    rgb VARCHAR(6),
    is_trans BOOLEAN DEFAULT FALSE
);

-- Create lego_parts table
CREATE TABLE IF NOT EXISTS lego_parts (
    part_num VARCHAR(20) PRIMARY KEY,
    name VARCHAR(250) NOT NULL,
    part_cat_id INTEGER
);

-- Create lego_sets table
CREATE TABLE IF NOT EXISTS lego_sets (
    set_num VARCHAR(20) PRIMARY KEY,
    name VARCHAR(256) NOT NULL,
    year INTEGER,
    theme_id INTEGER,
    num_parts INTEGER
);

-- Create lego_inventories table
CREATE TABLE IF NOT EXISTS lego_inventories (
    id SERIAL PRIMARY KEY,
    version INTEGER DEFAULT 1,
    set_num VARCHAR(20) REFERENCES lego_sets(set_num)
);

-- Create lego_inventory_parts table (main inventory tracking)
CREATE TABLE IF NOT EXISTS lego_inventory_parts (
    inventory_id INTEGER REFERENCES lego_inventories(id),
    part_num VARCHAR(20) REFERENCES lego_parts(part_num),
    color_id INTEGER REFERENCES lego_colors(id),
    quantity INTEGER NOT NULL CHECK (quantity > 0),
    is_spare BOOLEAN DEFAULT FALSE,
    PRIMARY KEY (inventory_id, part_num, color_id, is_spare)
);

-- Create indexes for better performance
CREATE INDEX IF NOT EXISTS idx_inventory_parts_inventory ON lego_inventory_parts(inventory_id);
CREATE INDEX IF NOT EXISTS idx_inventory_parts_part ON lego_inventory_parts(part_num);
CREATE INDEX IF NOT EXISTS idx_inventory_parts_color ON lego_inventory_parts(color_id);"}

{"sql": "-- Create audit logging table for tracking transfer history
CREATE TABLE IF NOT EXISTS inventory_transfer_log (
    log_id SERIAL PRIMARY KEY,
    transfer_timestamp TIMESTAMP DEFAULT NOW(),
    source_inventory_id INTEGER NOT NULL,
    target_inventory_id INTEGER NOT NULL,
    part_num VARCHAR NOT NULL,
    color_id INTEGER NOT NULL,
    quantity_transferred INTEGER NOT NULL,
    transfer_reason VARCHAR NOT NULL,
    transfer_status VARCHAR NOT NULL CHECK (transfer_status IN ('success', 'failed')),
    error_message TEXT
);

-- Create indexes for better query performance on the log table
CREATE INDEX IF NOT EXISTS idx_transfer_log_timestamp ON inventory_transfer_log(transfer_timestamp);
CREATE INDEX IF NOT EXISTS idx_transfer_log_source ON inventory_transfer_log(source_inventory_id);
CREATE INDEX IF NOT EXISTS idx_transfer_log_target ON inventory_transfer_log(target_inventory_id);
CREATE INDEX IF NOT EXISTS idx_transfer_log_status ON inventory_transfer_log(transfer_status);"}

{"sql": "CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id INTEGER,
    target_inventory_id INTEGER,
    part_to_transfer_num VARCHAR,
    color_to_transfer_id INTEGER,
    quantity_to_transfer INTEGER,
    transfer_reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    v_source_exists BOOLEAN;
    v_target_exists BOOLEAN;
    v_part_exists BOOLEAN;
    v_color_exists BOOLEAN;
    v_source_quantity INTEGER;
    v_source_spare_quantity INTEGER;
    v_total_available INTEGER;
    v_rows_affected INTEGER;
    v_error_message TEXT;
    v_success_message TEXT;
BEGIN
    -- Start transaction block with exception handling
    BEGIN
        -- Step A: Pre-validation

        -- Lock both inventory records to prevent race conditions
        PERFORM 1 FROM lego_inventories 
        WHERE id IN (source_inventory_id, target_inventory_id)
        FOR UPDATE;

        -- Validation A: Basic Checks

        -- Check if source inventory exists
        SELECT EXISTS(SELECT 1 FROM lego_inventories WHERE id = source_inventory_id)
        INTO v_source_exists;

        IF NOT v_source_exists THEN
            v_error_message := format('Source inventory ID %s does not exist', source_inventory_id);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Check if target inventory exists
        SELECT EXISTS(SELECT 1 FROM lego_inventories WHERE id = target_inventory_id)
        INTO v_target_exists;

        IF NOT v_target_exists THEN
            v_error_message := format('Target inventory ID %s does not exist', target_inventory_id);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Check if part exists
        SELECT EXISTS(SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num)
        INTO v_part_exists;

        IF NOT v_part_exists THEN
            v_error_message := format('Part number %s does not exist', part_to_transfer_num);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Check if color exists
        SELECT EXISTS(SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id)
        INTO v_color_exists;

        IF NOT v_color_exists THEN
            v_error_message := format('Color ID %s does not exist', color_to_transfer_id);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Validation B: Business Rules

        -- Prevent self-transfers
        IF source_inventory_id = target_inventory_id THEN
            v_error_message := 'Self-transfer not allowed: source and target inventory cannot be the same';
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Check minimum quantity
        IF quantity_to_transfer < 1 THEN
            v_error_message := format('Invalid transfer quantity %s: minimum is 1', quantity_to_transfer);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Check maximum quantity
        IF quantity_to_transfer > 500 THEN
            v_error_message := format('Invalid transfer quantity %s: maximum is 500', quantity_to_transfer);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Get available quantity from source (including spare parts)
        SELECT COALESCE(SUM(CASE WHEN is_spare = false THEN quantity ELSE 0 END), 0),
               COALESCE(SUM(CASE WHEN is_spare = true THEN quantity ELSE 0 END), 0)
        INTO v_source_quantity, v_source_spare_quantity
        FROM lego_inventory_parts
        WHERE inventory_id = source_inventory_id 
          AND part_num = part_to_transfer_num 
          AND color_id = color_to_transfer_id;

        v_total_available := v_source_quantity + v_source_spare_quantity;

        -- Check if source has sufficient quantity
        IF v_total_available < quantity_to_transfer THEN
            v_error_message := format('Insufficient quantity in source inventory: available %s, requested %s', 
                                    v_total_available, quantity_to_transfer);
            RAISE EXCEPTION '%', v_error_message;
        END IF;

        -- Step B: Source Inventory Update

        -- First, try to fulfill from non-spare parts
        IF v_source_quantity >= quantity_to_transfer THEN
            -- Update non-spare parts
            UPDATE lego_inventory_parts
            SET quantity = quantity - quantity_to_transfer
            WHERE inventory_id = source_inventory_id 
              AND part_num = part_to_transfer_num 
              AND color_id = color_to_transfer_id
              AND is_spare = false;

            -- Delete if quantity becomes zero
            DELETE FROM lego_inventory_parts
            WHERE inventory_id = source_inventory_id 
              AND part_num = part_to_transfer_num 
              AND color_id = color_to_transfer_id
              AND is_spare = false
              AND quantity = 0;
        ELSE
            -- Need to use both non-spare and spare parts
            DECLARE
                v_remaining_needed INTEGER;
            BEGIN
                v_remaining_needed := quantity_to_transfer;

                -- First, use all non-spare parts
                IF v_source_quantity > 0 THEN
                    v_remaining_needed := v_remaining_needed - v_source_quantity;

                    DELETE FROM lego_inventory_parts
                    WHERE inventory_id = source_inventory_id 
                      AND part_num = part_to_transfer_num 
                      AND color_id = color_to_transfer_id
                      AND is_spare = false;
                END IF;

                -- Then use spare parts for the remainder
                UPDATE lego_inventory_parts
                SET quantity = quantity - v_remaining_needed
                WHERE inventory_id = source_inventory_id 
                  AND part_num = part_to_transfer_num 
                  AND color_id = color_to_transfer_id
                  AND is_spare = true;

                -- Delete spare parts if quantity becomes zero
                DELETE FROM lego_inventory_parts
                WHERE inventory_id = source_inventory_id 
                  AND part_num = part_to_transfer_num 
                  AND color_id = color_to_transfer_id
                  AND is_spare = true
                  AND quantity = 0;
            END;
        END IF;

        -- Step C: Target Inventory Update

        -- Check if part already exists in target inventory (non-spare)
        IF EXISTS (
            SELECT 1 FROM lego_inventory_parts
            WHERE inventory_id = target_inventory_id 
              AND part_num = part_to_transfer_num 
              AND color_id = color_to_transfer_id
              AND is_spare = false
        ) THEN
            -- Update existing record
            UPDATE lego_inventory_parts
            SET quantity = quantity + quantity_to_transfer
            WHERE inventory_id = target_inventory_id 
              AND part_num = part_to_transfer_num 
              AND color_id = color_to_transfer_id
              AND is_spare = false;
        ELSE
            -- Insert new record
            INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
            VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id, quantity_to_transfer, false);
        END IF;

        -- Step D: Audit Logging for successful transfer
        INSERT INTO inventory_transfer_log (
            source_inventory_id,
            target_inventory_id,
            part_num,
            color_id,
            quantity_transferred,
            transfer_reason,
            transfer_status,
            error_message
        ) VALUES (
            source_inventory_id,
            target_inventory_id,
            part_to_transfer_num,
            color_to_transfer_id,
            quantity_to_transfer,
            transfer_reason,
            'success',
            NULL
        );

        -- Prepare success message
        v_success_message := format('Successfully transferred %s parts (%s, color_id: %s) from inventory %s to inventory %s. Reason: %s',
                                  quantity_to_transfer,
                                  part_to_transfer_num,
                                  color_to_transfer_id,
                                  source_inventory_id,
                                  target_inventory_id,
                                  transfer_reason);

        RETURN v_success_message;

    EXCEPTION
        WHEN OTHERS THEN
            -- Log failed transfer attempt
            INSERT INTO inventory_transfer_log (
                source_inventory_id,
                target_inventory_id,
                part_num,
                color_id,
                quantity_transferred,
                transfer_reason,
                transfer_status,
                error_message
            ) VALUES (
                source_inventory_id,
                target_inventory_id,
                part_to_transfer_num,
                color_to_transfer_id,
                quantity_to_transfer,
                transfer_reason,
                'failed',
                SQLERRM
            );

            -- Re-raise the exception to ensure transaction rollback
            RAISE;
    END;
END;
$$;"}

